from pathlib import Path
import re

js_path=Path('app.js')
css_path=Path('app.css')
s=js_path.read_text()
css=css_path.read_text()

# Preserve existing local saves while advancing the displayed prototype revision.
s=s.replace('ASHEN MARCHES · P0.1B','ASHEN MARCHES · P0.1C')

old="battle={region:i,enemies,party,target:0,resolve:30,turn:0,guard:0,dread:0,paused:false};"
new="battle={region:i,enemies,party,target:0,resolve:30,turn:0,guard:0,dread:0,paused:false,lastAction:'HUNTERS ENTER FORMATION'};"
if old in s:
    s=s.replace(old,new)
elif "lastAction:'HUNTERS ENTER FORMATION'" not in s:
    raise SystemExit('startBattle target not found')

# Add readable combat-state feedback without altering numerical combat balance.
s=s.replace("const b=battle;b.turn++;", "const b=battle;b.turn++;b.lastAction='FORMATION EXCHANGE';")
s=s.replace("if(e.cls==='bell'&&b.turn%4===0){b.dread=2;x.status.mark=2}", "if(e.cls==='bell'&&b.turn%4===0){b.dread=2;x.status.mark=2;b.lastAction='THE BELL MARKS A HUNTER'}")
s=s.replace("if(e.cls==='warden'&&b.turn%3===0){b.dread=2;x.status.mark=2}", "if(e.cls==='warden'&&b.turn%3===0){b.dread=2;x.status.mark=2;b.lastAction='THE WARDEN TOLLS'}")

battle_view=r'''function battleView(){if(!battle)return mapView();const r=REGIONS[battle.region],enemyMax=battle.enemies.reduce((a,x)=>a+x.max,0),enemyHp=battle.enemies.reduce((a,x)=>a+x.hp,0),partyMax=battle.party.reduce((a,x)=>a+x.max,0),partyHp=battle.party.reduce((a,x)=>a+x.hp,0),enemyPct=Math.round(100*enemyHp/enemyMax),partyPct=Math.round(100*partyHp/partyMax);return `<main class="battleview"><section class="battlescene zone-${r.kind}">${sceneSvg(r.kind)}<div class="battlecallout">${esc(battle.lastAction||'FORMATION ENGAGED')}</div><div class="enemyformation">${battle.enemies.map((e,i)=>unitEnemy(e,i)).join('')}</div><div class="allyformation">${battle.party.map((u,i)=>unitAlly(u,i)).join('')}</div></section><section class="combatbar"><div class="combatmeta"><div><small>${r.name.toUpperCase()}</small><b>TURN ${battle.turn}</b></div><div class="combatvitals"><span>HUNTERS ${partyPct}%</span><i class="allymeter"><em style="width:${partyPct}%"></em></i><span>THREAT ${enemyPct}%</span><i class="enemymeter"><em style="width:${enemyPct}%"></em></i></div><div class="resolve"><span>RESOLVE ${Math.floor(battle.resolve)}/100</span><i><em style="width:${battle.resolve}%"></em></i></div></div><div class="abilities"><button data-ability="focus" ${battle.resolve<30?'disabled':''}><b>⌖ FOCUS</b><small>30 · burst</small></button><button data-ability="sever" ${battle.resolve<40||!living('Duelist')?'disabled':''}><b>╱ SEVER</b><small>40 · bleed</small></button><button data-ability="guard" ${battle.resolve<25||!living('Vanguard')?'disabled':''}><b>⛨ BRACE</b><small>25 · guard</small></button><button data-ability="heal" ${battle.resolve<35||!living('Physician')?'disabled':''}><b>✚ TREAT</b><small>35 · heal</small></button></div><button class="retreat" data-retreat>RETREAT FROM THE MARCH</button></section></main>`}'''
s,n=re.subn(r"function battleView\(\)\{.*?\}\nfunction unitEnemy", battle_view+'\nfunction unitEnemy', s, count=1, flags=re.S)
if n!=1: raise SystemExit('battleView replacement failed')

units=r'''function unitEnemy(u,i){return `<button class="battleunit enemy cls-${u.cls} row-${u.row} ${u.hp<=0?'down':''} ${battle.target===i?'target':''}" data-target="${i}" ${u.hp<=0?'disabled':''}>${battle.target===i?'<span class="reticle">TARGET</span>':''}${enemySvg(u.cls,u.name)}<b>${esc(u.name)}</b><div class="unitbar"><i style="width:${100*u.hp/u.max}%"></i></div><small>${u.hp}/${u.max}${statusText(u)}</small></button>`}
function unitAlly(u,i){return `<div class="battleunit ally hunter-${u.id||'guard'} row-${u.row} ${u.hp<=0?'down':''}">${hunterSvg(u.id||'guard')}<b>${u.name}</b><div class="unitbar"><i style="width:${100*u.hp/u.max}%"></i></div><small>${u.hp}/${u.max}${statusText(u)}</small></div>`}
function statusText'''
s,n=re.subn(r"function unitEnemy\(u,i\)\{.*?\}\nfunction statusText", units, s, count=1, flags=re.S)
if n!=1: raise SystemExit('unit rendering replacement failed')

ability=r'''function ability(a){if(!battle)return;const b=battle,t=targetEnemy(),w=alive(b.party).sort((x,y)=>x.hp/x.max-y.hp/y.max)[0];if(a==='focus'&&b.resolve>=30&&t){b.resolve-=30;hit(t,36+Math.random()*12);b.lastAction=`FOCUS STRIKE · ${t.name.toUpperCase()}`}else if(a==='sever'&&b.resolve>=40&&t&&living('Duelist')){b.resolve-=40;hit(t,45);t.status.bleed=3;t.status.broken=2;b.lastAction=`SEVER · ${t.name.toUpperCase()} BROKEN`}else if(a==='guard'&&b.resolve>=25&&living('Vanguard')){b.resolve-=25;b.guard=2;b.lastAction='VANGUARD BRACES THE LINE'}else if(a==='heal'&&b.resolve>=35&&w&&living('Physician')){b.resolve-=35;w.hp=Math.min(w.max,w.hp+40+G.buildings.infirmary*5);w.status.bleed=0;w.status.mark=0;b.lastAction=`FIELD TREATMENT · ${w.name.toUpperCase()}`}if(!alive(b.enemies).length)return victory();render()}'''
s,n=re.subn(r"function ability\(a\)\{.*?\}\nfunction retreat", ability+'\nfunction retreat', s, count=1, flags=re.S)
if n!=1: raise SystemExit('ability replacement failed')

art=r'''function sceneSvg(kind){const chapel=kind==='chapel'||kind==='warden'||kind==='title',farm=kind==='farm',cause=kind==='causeway',enclave=kind==='enclave'||kind==='hall',map=kind==='map',boss=kind==='warden'||kind==='title';return `<svg viewBox="0 0 800 500" class="scene scene-${kind}" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="sky-${kind}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#4f6068"/><stop offset=".42" stop-color="#27343a"/><stop offset="1" stop-color="#090d10"/></linearGradient><linearGradient id="mist-${kind}" x1="0" y1="0" x2="1" y2="0"><stop stop-color="#d5d7d0" stop-opacity="0"/><stop offset=".5" stop-color="#c7cdc8" stop-opacity=".18"/><stop offset="1" stop-color="#889397" stop-opacity="0"/></linearGradient><filter id="soft-${kind}"><feGaussianBlur stdDeviation="7"/></filter></defs><rect width="800" height="500" fill="url(#sky-${kind})"/><circle cx="650" cy="78" r="34" fill="#d6d3c8" opacity=".12"/><g fill="#141c20" opacity=".72"><path d="M0 260L55 238 95 246 132 210 174 236 214 202 250 230 310 198 356 235 420 205 471 226 530 188 590 221 650 194 720 228 800 205V350H0Z"/></g><path d="M0 334C125 294 245 342 358 310S635 280 800 320V500H0Z" fill="#10171a"/><path d="M0 385C175 340 280 404 454 354S690 342 800 374V500H0Z" fill="#080d10"/>${enclave?`<g stroke="#435159" stroke-width="3"><path d="M40 358V270L92 238 132 254 180 218 232 251V358Z" fill="#11191d"/><path d="M242 358V238L315 198 392 238V358Z" fill="#151e22"/><path d="M405 358V212L468 182 536 220V358Z" fill="#11191d"/><path d="M550 358V248L622 214 710 252V358Z" fill="#151d21"/><path d="M500 215V122H527V215M486 126h56" fill="#0e1417"/><path d="M0 350H800V382H0Z" fill="#0b1013"/><g stroke="#6f7d80" opacity=".42"><path d="M22 350v-38m38 38v-48m44 48v-44m558 44v-45m43 45v-39m44 39v-50"/></g></g><g fill="#8e6e4f" opacity=".24"><rect x="283" y="265" width="20" height="13"/><rect x="332" y="257" width="18" height="11"/><rect x="443" y="260" width="19" height="12"/><rect x="612" y="278" width="16" height="10"/></g>`:''}${farm?`<g><path d="M67 367V252L171 185 288 248V367Z" fill="#11181c" stroke="#3d484d" stroke-width="3"/><path d="M98 267h158M118 367v-82h61v82" stroke="#596469" stroke-width="4" opacity=".45"/><path d="M522 367V214h60v153M505 214h95l-18-63h-51Z" fill="#131b1e" stroke="#455157" stroke-width="3"/><path d="M608 360l28-111 27 111M636 249l-46-40m46 40 52-38" stroke="#3d474b" stroke-width="5"/><path d="M324 370l20-104m-20 34-55-43m58 61 72-62" stroke="#171e21" stroke-width="9"/><path d="M0 397L800 351" stroke="#68777b" stroke-opacity=".18" stroke-width="18"/><g stroke="#59666b" opacity=".45"><path d="M7 375v-48m0 22h110m45 14h116m40-8h145m86 8h184"/></g></g>`:''}${cause?`<g><path d="M-20 333L250 306 316 350 468 303 830 330" stroke="#222d32" stroke-width="62" fill="none"/><path d="M252 303l70 91M472 300l-43 103" stroke="#080c0e" stroke-width="24"/><path d="M65 214h48v120M678 198h48v132" stroke="#263238" stroke-width="28"/><path d="M66 210h51m559-17h54" stroke="#667378" stroke-width="5"/><path d="M343 317l73-9 25 18-9 35-84 6-22-18Z" fill="#161d21" stroke="#4d595e" stroke-width="3"/><rect x="365" y="320" width="28" height="15" fill="#758085" opacity=".22"/><path d="M95 212C260 167 552 155 704 198" fill="none" stroke="#657277" stroke-width="2" opacity=".42"/></g>`:''}${chapel?`<g><path d="M445 367V194h190v173Z" fill="#11171b" stroke="#414b50" stroke-width="3"/><path d="M425 194l115-108 118 108Z" fill="#151c20" stroke="#4a555a" stroke-width="3"/><path d="M524 90V31h31v59m-18-43h47" stroke="#1a2226" stroke-width="13"/><path d="M505 367v-121h66v121" fill="#080d10"/><path d="M463 230h28v54h-28m128-54h27v54h-27" fill="#273238" opacity=".55"/><g stroke="#303b40" stroke-width="6"><path d="M60 365v-78m-22 25h44M132 371v-63m-19 20h38M208 365v-84m-24 24h48M305 370v-58m-18 19h36"/></g>${boss?`<path d="M145 367V132h142v235Z" fill="#0e1417" stroke="#3c474c" stroke-width="4"/><path d="M163 132l25-104h56l25 104Z" fill="#12191d"/><circle cx="216" cy="171" r="35" fill="#05090b" stroke="#596368" stroke-width="5"/><path d="M216 138v67M184 171h64" stroke="#3d474c" stroke-width="5"/><path d="M96 368h242" stroke="#222c31" stroke-width="16"/>`:''}</g>`:''}${map?`<g><path d="M18 411L157 278 283 320 415 194 577 142 748 174 812 150V430H18Z" fill="#10171a"/><path d="M78 410C147 353 205 338 265 323S382 269 442 223 589 180 705 139" fill="none" stroke="#8c999b" stroke-width="8" stroke-opacity=".2" stroke-dasharray="12 14"/><g stroke="#526066" stroke-width="2" opacity=".28"><path d="M120 342c85-54 171-39 244-82s158-81 275-85"/><path d="M94 378c114-58 205-43 292-94s169-71 292-77"/><path d="M170 414c106-42 173-32 258-74s147-60 238-55"/></g></g>`:''}<g filter="url(#soft-${kind})" opacity=".75"><ellipse cx="192" cy="302" rx="260" ry="47" fill="url(#mist-${kind})"/><ellipse cx="624" cy="267" rx="285" ry="51" fill="url(#mist-${kind})"/></g><g stroke="#d9ddd7" stroke-opacity=".12">${Array.from({length:24},(_,i)=>`<path d="M${i*38-90} ${i%3*15}l150 500"/>`).join('')}</g></svg>`}
function hunterSvg(id){const v=id==='vanguard',d=id==='duelist',p=id==='physician',g=id==='guard',sc=id==='scout';return `<svg viewBox="0 0 100 160" class="figure"><g class="hunter-art"><path d="M42 12h16l7 10-5 20H40l-6-20Z" fill="#9ca7a8" opacity=".82"/><path d="M${v||g?20:27} 43Q50 29 ${v||g?80:73} 43L${v||g?86:76} 118 66 153H54L50 101 45 153H32L${v||g?13:23} 119Z" fill="${p?'#48575b':sc?'#354348':d?'#30383d':'#344148'}" stroke="#819094" stroke-width="2"/>${v?'<path d="M13 55h24v61H13Z" fill="#232c30" stroke="#9aa5a5" stroke-width="3"/><path d="M78 50l13 72" stroke="#c3c8c3" stroke-width="5"/>':''}${d?'<path d="M74 50l20 78" stroke="#c7cbc6" stroke-width="4"/><path d="M23 56l-12 49" stroke="#7e8c8f" stroke-width="4"/><path d="M35 46l-7 65" stroke="#1f272b" stroke-width="12"/>':''}${p?'<path d="M36 18l-15 14 18 7" fill="#b7c0bd"/><path d="M50 60v29M35 74h30" stroke="#c7ceca" stroke-width="5" opacity=".7"/><circle cx="76" cy="91" r="10" fill="#b69c70" opacity=".55"/>':''}${g?'<path d="M10 53h28v65H10Z" fill="#293337" stroke="#849194" stroke-width="3"/><path d="M74 52l17 70" stroke="#aab2af" stroke-width="5"/>':''}${sc?'<path d="M28 28q22-28 44 0l-7 17H35Z" fill="#253035"/><path d="M70 49q27 31 3 76" fill="none" stroke="#9ca7a6" stroke-width="3"/><path d="M72 52l18 73" stroke="#565f61" stroke-width="3"/>':''}<path d="M33 151h16m7 0h16" stroke="#11171a" stroke-width="5"/></g></svg>`}
function enemySvg(cls,name=''){const boss=cls==='warden',husk=cls==='husk',hound=/Hound/i.test(name),bell=cls==='bell',serv=cls==='servitor',ranged=['rifleman','spotter'].includes(cls),reaver=cls==='reaver';if(hound)return `<svg viewBox="0 0 110 160" class="figure enemyfig"><g transform="translate(0 42)"><path d="M10 68Q25 35 58 44L88 63 101 104H88L78 78 62 84 52 116H40L42 82 20 82 17 112H5Z" fill="#32383a" stroke="#777b79" stroke-width="3"/><path d="M70 47l16-25 5 33" fill="#4a4b48"/><circle cx="87" cy="50" r="3" fill="#b8a173"/></g></svg>`;return `<svg viewBox="0 0 110 170" class="figure enemyfig"><g><path d="M42 11h26l8 15-8 22H41l-7-22Z" fill="${boss?'#8a827d':'#777a77'}" opacity=".75"/><path d="M${boss?10:23} 49Q55 ${boss?24:36} ${boss?100:87} 49L${boss?104:91} 130 73 166H58L54 106 47 166H31L${boss?4:17} 130Z" fill="${boss?'#403c3b':husk?'#4a5152':bell?'#33383a':serv?'#34383a':'#292f32'}" stroke="#746f6b" stroke-width="3"/>${ranged?'<path d="M61 62l43 20" stroke="#a09b92" stroke-width="6"/><path d="M88 72l10 35" stroke="#555b5c" stroke-width="3"/>':''}${reaver?'<path d="M17 61l-13 68M86 57l18 65" stroke="#8b8983" stroke-width="6"/>':''}${husk?'<path d="M25 55l-12 72M88 57l12 65" stroke="#50595a" stroke-width="9"/><path d="M31 40h49" stroke="#9b958b" stroke-width="5" opacity=".45"/>':''}${bell?'<path d="M73 66l19 7-5 28-25-9Z" fill="#67635e"/><path d="M87 101v30" stroke="#8b8275" stroke-width="4"/>':''}${serv?'<path d="M26 68h58M31 88h49" stroke="#8d8780" stroke-width="4" opacity=".45"/>':''}${boss?'<path d="M12 50L2 142M98 50l10 92" stroke="#9b918b" stroke-width="8"/><path d="M29 37h54" stroke="#aea39a" stroke-width="7"/><path d="M55 3v35" stroke="#6f6965" stroke-width="5"/>':''}</g></svg>`}
function debugState'''
s,n=re.subn(r"function sceneSvg\(kind\)\{.*?\}\nfunction debugState", art, s, count=1, flags=re.S)
if n!=1: raise SystemExit('art replacement failed')

marker='/* P01C_VISUAL_POLISH */'
if marker not in css:
    css += r'''
/* P01C_VISUAL_POLISH */
.scene{filter:contrast(1.08) saturate(.78)}
.titleart .scene{filter:contrast(1.12) saturate(.7)}
.worldscene:before,.marchmap:before,.battlescene:before{content:'';position:absolute;z-index:3;inset:0;pointer-events:none;background:radial-gradient(circle at 50% 55%,transparent 0 42%,rgba(1,4,6,.34) 78%,rgba(1,3,5,.7) 100%)}
.hotspot{border-color:#788387;background:linear-gradient(180deg,rgba(17,24,28,.9),rgba(6,10,12,.88));box-shadow:0 7px 24px rgba(0,0,0,.64),inset 0 1px rgba(255,255,255,.04)}
.battlecallout{position:absolute;z-index:12;top:12px;left:50%;transform:translateX(-50%);max-width:74%;padding:6px 11px;border:1px solid rgba(164,173,171,.42);background:linear-gradient(90deg,rgba(5,8,10,.18),rgba(8,12,14,.86),rgba(5,8,10,.18));font:700 8px/1.2 Georgia,serif;letter-spacing:1.5px;color:#d8d6cd;text-align:center;text-shadow:0 1px 8px #000;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;animation:callout-in .28s ease-out}
@keyframes callout-in{from{opacity:0;transform:translate(-50%,-5px)}to{opacity:1;transform:translate(-50%,0)}}
.enemyformation{top:48px;bottom:34%}.allyformation{bottom:16px}
.battleunit .figure{filter:drop-shadow(0 8px 5px rgba(0,0,0,.68));transform-origin:50% 100%;animation:unit-enter .34s ease-out}
@keyframes unit-enter{from{opacity:.35;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}
.battleunit.enemy.target{border-color:#b59b6b;background:radial-gradient(circle at 50% 45%,rgba(105,77,45,.28),rgba(18,14,11,.42));box-shadow:0 0 0 1px rgba(181,155,107,.18),0 0 18px rgba(151,113,64,.16)}
.battleunit.enemy.target .figure{filter:drop-shadow(0 0 7px rgba(196,166,107,.5)) drop-shadow(0 8px 5px rgba(0,0,0,.7));animation:target-breathe 1.1s ease-in-out infinite alternate}
@keyframes target-breathe{from{transform:translateY(0) scale(1)}to{transform:translateY(-2px) scale(1.025)}}
.reticle{position:absolute;left:50%;top:-13px;transform:translateX(-50%);font-size:6px;letter-spacing:1.2px;color:#d3b77e;background:#1b140d;border:1px solid #806b46;padding:2px 4px;box-shadow:0 2px 8px #000}
.battleunit.enemy{position:relative}.battleunit.enemy.down .figure{transform:rotate(8deg) translateY(12px);transform-origin:50% 100%;animation:none}
.battleunit.ally.down .figure{transform:rotate(-8deg) translateY(10px);animation:none}
.cls-warden .figure{width:76px!important;height:132px!important}.cls-husk .figure{width:62px}.cls-bell .figure{filter:drop-shadow(0 0 5px rgba(132,113,87,.2)) drop-shadow(0 8px 5px rgba(0,0,0,.68))}
.combatmeta{gap:8px}.combatvitals{width:31%;min-width:94px}.combatvitals span{display:block;font-size:5.8px;letter-spacing:.5px;color:#89969a;line-height:1}.combatvitals i{display:block;height:3px;background:#242d31;margin:2px 0 4px}.combatvitals em{display:block;height:100%}.combatvitals .allymeter em{background:#778d91}.combatvitals .enemymeter em{background:#8f514d}.resolve{width:34%}
.abilities button{position:relative;overflow:hidden;min-width:0;padding:5px 2px}.abilities button:after{content:'';position:absolute;inset:0;background:linear-gradient(120deg,transparent 30%,rgba(255,255,255,.04),transparent 70%);pointer-events:none}.abilities b{display:block;font-size:7px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.abilities small{font-size:5.8px;margin-top:3px}.abilities button:not(:disabled):active{transform:translateY(1px);filter:brightness(1.22)}
.zone-farm .battlescene,.zone-farm{--zone:#6f766d}.zone-causeway{--zone:#66747a}.zone-chapel{--zone:#77706b}.zone-warden{--zone:#7c645f}
.zone-warden .battlecallout{border-color:#72504c;color:#d0b4ad}.zone-warden .battlescene:after{background:linear-gradient(0deg,rgba(15,5,6,.72),transparent 31%),repeating-linear-gradient(174deg,transparent 0 24px,rgba(220,225,219,.018) 25px 26px)}
.hunterportrait.selected .figure{filter:drop-shadow(0 0 8px rgba(154,174,177,.25))}.hunterportrait .figure{filter:drop-shadow(0 7px 5px rgba(0,0,0,.55))}
.mapnode.open:not(.cleared){animation:node-pulse 2.6s ease-in-out infinite alternate}@keyframes node-pulse{from{box-shadow:0 5px 18px #000}to{box-shadow:0 5px 18px #000,0 0 15px rgba(151,166,166,.18)}}
.rarity-relic{background:linear-gradient(90deg,#1b1712,#0b1012);box-shadow:inset 3px 0 0 #b09061,0 0 14px rgba(176,144,97,.08)}
'''

js_path.write_text(s)
css_path.write_text(css)
print('Applied Prototype 0.1c visual and combat-feel polish without changing combat math.')
